edits.replacement:
#root #setlist #set_auto::after, #root #setlist #set_share::after{ font-size:var(--fs-title); color:var(--tx-2); }
/* v28.xx (cw-diffarrow): the difficulty button had no arrows, so it read as a link to another page, not a switch like every row under it; it now has the same pair */
#root #setlist #set_diff{ display:inline-flex; align-items:center; justify-content:space-between; gap:10px; }
#root #setlist #set_diff::before{ content:'\2039'; }
#root #setlist #set_diff::after{ content:'\203A'; }
#root #setlist #set_diff::before, #root #setlist #set_diff::after{ font-size:var(--fs-title); color:var(--tx-2); line-height:1; }
#root #setlist #set_diff.padfocus::before, #root #setlist #set_diff.padfocus::after{ color:var(--acc); }

check:
{v:'VER',what:'the difficulty button in Settings has the same two arrows as every other switch in the list (it read as a link to another page)',
 run:function(){
   if(typeof diffRowHtml!=='function') return 'no difficulty row';
   var bad=[], b, g, i, p, x, y;
   try{
     __topClear(); __runPrep(); SETSUB=''; renderSettings();
     b=document.getElementById('set_diff'); g=document.querySelector('#setlist .row > button[id^="go_"]');
     if(!b) bad.push('no difficulty button on the Settings page');
     else if(!g) bad.push('no other switch on the Settings page to compare with');
     else {
       for(p=['::before','::after'],i=0;i<p.length;i++){
         x=getComputedStyle(b,p[i]).content; y=getComputedStyle(g,p[i]).content;
         if(!x||x==='none'||x==='normal') bad.push('the difficulty button has no '+(i?'right':'left')+' arrow');
         else if(x!==y) bad.push('the difficulty button '+(i?'right':'left')+' arrow is '+x+', the other switches show '+y);
       }
       if(getComputedStyle(b).display!==getComputedStyle(g).display) bad.push('the difficulty button lays out as '+getComputedStyle(b).display+', the other switches as '+getComputedStyle(g).display);
     }
   } catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ SETSUB=''; try{ renderSettings(); __topClear(); }catch(_f){} }
   return bad.length?bad.join('; '):null; }},
